            evidence_expectation=cast(str, _field(source, "evidence_expectation")),
            status=status,
            acceptance_criteria=cast(str | None, _optional(source, "acceptance_criteria")),
            requested_items=(
                ()
                if requested is None
                else tuple(_decode_requested_item(item) for item in _array(requested))
            ),
            source_refs=(
                () if source_refs is None else cast(tuple[EventId, ...], tuple(_array(source_refs)))
            ),
            resolution_evidence_refs=(
                ()
                if resolution_refs is None
                else cast(
                    tuple[EvidenceId | ResultId, ...],
                    tuple(_array(resolution_refs)),
                )
            ),
        )
    if schema.name == "assignment_recorded":
        obligations = tuple(_array(_field(source, "obligation_ids")))
        write_policy_value = _optional(source, "write_policy")
        handoff = _optional(source, "handoff_of")
        return AssignmentRecordedPayload(
            assignee_actor_id=actor_id(_field(source, "assignee_actor_id")),
            obligation_ids=cast(tuple[ObligationId, ...], obligations),
            scope_description=cast(str, _field(source, "scope_description")),
    findings: Mapping[FindingId, ProjectionRecord[Finding]],
    responses: Mapping[FindingId, ProjectionRecord[ResponseRecordedPayload]],
) -> tuple[str, ...]:
    gaps = {marker for marker in retained_gaps if not marker.startswith("missing_ref:")}

    def require(source_event: EventId, target: str) -> None:
        if not _target_visible(
            target,
            obligations,
            actions,
            results,
            evidence,
            claims,
            findings,
        ):
            gaps.add(f"missing_ref:{source_event}:{target}")

    for record in plans.values():
        payload = record.payload
        if type(payload) is PlanPublishedPayload:
            for target in payload.obligation_refs:
                require(record.source_event_id, target)
        elif type(payload) is PlanRevisedPayload:
            for change in payload.obligation_changes:
                require(record.source_event_id, change.obligation_id)
                for target in change.replacement_obligation_ids:
                    require(record.source_event_id, target)
    for record in obligations.values():
        if record.payload is not None:
            for target in record.payload.resolution_evidence_refs:
                require(record.source_event_id, target)
